def search(arr):
    """
    Finds the element that appears only once in a sorted array.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2

        # Check if mid is the single element
        if (mid == 0 or arr[mid] != arr[mid - 1]) and (mid == len(arr) - 1 or arr[mid] != arr[mid + 1]):
            return arr[mid]

        # Check if the left half is complete pairs
        if mid % 2 == 0:
            if mid + 1 < len(arr) and arr[mid] == arr[mid + 1]:
                left = mid + 2
            else:
                right = mid - 1
        else:
            if mid - 1 >= 0 and arr[mid] == arr[mid - 1]:
                left = mid + 1
            else:
                right = mid - 2

    return None

