def reverse_vowels(s):
    """
    Reverses only the vowels in the given string.
    """
    vowels = "AEIOUaeiou"
    s_list = list(s)
    i, j = 0, len(s) - 1

    while i < j:
        if s_list[i] in vowels and s_list[j] in vowels:
            s_list[i], s_list[j] = s_list[j], s_list[i]
            i += 1
            j -= 1
