def get_max_sum(n, memo={}):
    """
    Returns the maximum sum possible by using the given equation f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n).
    """
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    if n == 1:
        return 1

    max_sum = max(
        get_max_sum(n // 2, memo) + get_max_sum(n // 3, memo) + get_max_sum(n // 4, memo) + get_max_sum(n // 5, memo),
