def find_kth(arr1, arr2, k):
    """
    Find the kth element in two sorted arrays.
    """
    i, j = 0, 0
    while i < len(arr1) and j < len(arr2) and i + j < k - 1:
        if arr1[i] < arr2[j]:
            i += 1
        else:
            j += 1

    if i + j == k - 1:
        if i < len(arr1) and j < len(arr2):
            return min(arr1[i], arr2[j])
        elif i < len(arr1):
            return arr1[i]
        else:
            return arr2[j]
    elif i + j < k - 1:
        if i < len(arr1):
            return arr1[i + (k - 1 - i - j)]
        else:
            return arr2[j + (k - 1 - i - j)]
    else:
        if i > 0:
            return arr1[i - 1]
        else:
            return arr2[j - 1]

